function article(root,title,subtitle){const p=el('article',undefined,'panel');p.append(el('h2',title));if(subtitle)p.append(el('p',subtitle));root.append(p);return p;}
function table(target,headers,rows){const wrap=el('div',undefined,'garantia-table-wrap');const t=el('table'),head=el('thead'),tr=el('tr');for(const h of headers)tr.append(el('th',h));head.append(tr);t.append(head);const body=el('tbody');for(const row of rows){const tr=el('tr');row.forEach((v,i)=>{const td=el('td');td.dataset.label=headers[i];if(v instanceof Node)td.append(v);else td.textContent=String(v??'—');tr.append(td);});body.append(tr);}if(!rows.length){const tr=el('tr'),td=el('td','Nenhum registro nesta seleção.');td.colSpan=headers.length;tr.append(td);body.append(tr);}t.append(body);wrap.append(t);target.append(wrap);return wrap;}
function download(name,body,type='application/json'){const u=URL.createObjectURL(new Blob([body],{type}));const a=el('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function m(){return mesEstado(state,month);}
