 a.append(button('Novo lançamento manual',()=>metricEditor('', 'todos'),'primary'));table(a,['Escopo','Origem','Ação'],Object.entries(m().metricas).map(([k,v])=>[k,v.origem||'Importação',button('Editar',()=>metricEditor(k,k.startsWith('PESSOA:')?'individual':'todos'))]));const scopes=article(roots.lancamentos,'Chaves para lançamentos individuais','Copie o escopo ao mapear uma planilha de Chamevolks/AEG.');table(scopes,['Colaborador','Escopo individual'],m().participantes.filter(p=>p.perfil==='assistente').map(p=>[p.nome,'PESSOA:'+chavePessoa(p)]));
