function renderPolicies(){const a=article(roots.politicas,'Políticas da Garantia','Versões de junho/julho de 2025 e definições confirmadas em 22/10/2026. As regras são separadas por perfil.');for(const text of ['Malote: coleta até o prazo Mônaco é CONFORME; após o prazo é NÃO CONFORME. Conformidade = conformes / (conformes + não conformes) × 100, pelos lançamentos do mês selecionado. Datas incompletas deixam o percentual pendente. A quantidade de processos vem das notas fechadas e não é o denominador desta amostra de malotes.','Local: até 100 processos, base de R$300. De 101 a 300, R$3,50 por processo para assistente e R$2,50 para auxiliar; a partir de 301, R$3 e R$2. Assistente Adm. PV de Bacabal segue assistente local.','Local: exige faturamento ≥80% e malote ≥75%. Cumpridos os mínimos, aplica o percentual real de faturamento, limitado a 100%, à base. Abaixo dos mínimos, não habilita. Sem exceção: o percentual não é arredondado para atingir o mínimo. Valores do Excel abaixo desse limite ficam apenas como referência, sem liberar bonificação.','Local: devolutivas >5% descontam 30% (definição confirmada); frete elegível pendente desconta 20%; divergência físico × fiscal >5% desconta 30%; pendências de arquivamento NF e SG descontam 5% cada. Descontos são somados sobre o bônus habilitado. Frete exclui o mês anterior, conforme política.','Analistas: faturamento 80/90/100% paga R$300/400/600; recebimento 80/90/100% paga R$150/200/300; inserção 75/80/100% paga R$150/200/300.','Analistas: extra de R$600 exige todas as unidades vinculadas com pelo menos 100% em faturamento, recebimento e inserção; erros ≥5% cancelam o extra e descontam 30%. Destaque do mês de R$300 exige indicação nominal justificada. O comparativo de desempenho reproduz a média de cinco componentes das fórmulas da planilha, com cancelamentos abaixo de 0,5% (confirmado); o prêmio não é atribuído automaticamente.','Assistentes da Central: até R$500 nos três indicadores, mais R$200 por status AEG (Aguardando preenchimento e Correção, não conformidade <5%, D+2), total até R$900, mais R$25 por Chamevolks individual faturado.','Gestão: até R$2.400 por pessoa nos quatro indicadores. Recebimento acima de 100% acrescenta R$150 por bloco completo de 5 pontos percentuais.','Cancelamento de notas: indicador preparado, atualmente não cobrado. Os registros são informativos e não geram desconto na bonificação. A referência histórica de desempenho não autoriza cobrança.', 'Central: erros ≥5% descontam 30% sobre o bônus total. Faturamento é O.S. fechadas / abertas na validação recebida. Recebimento é valor recebido / faturado no respectivo mês. Não confundir percentuais com valores monetários ou médias simples de filiais.','O sistema preserva as referências originais para comparação e nunca executa fórmulas do Excel. Campos vazios permanecem pendentes. NA explícito nas penalidades da bonificação é tratado como não aplicável por pessoa, com identificação no detalhamento; ele não preenche o campo numérico com zero. Consolidados GERAL e ANALISTA são explícitos: revise-os ao alterar unidades.','A sincronização criptografada usa a tabela de configurações de Campanhas existente. Abra a nuvem com sua senha em cada sessão para ativar as gravações automáticas. Mantenha backups; não há recuperação da senha. Exportar não efetua pagamento.'])a.append(el('p',text));const p=article(roots.politicas,'Faixas da Central e gestão');table(p,['Indicador','Regra','Assistente','Líder / supervisora'],POLITICA_GARANTIA.indicadores.map(r=>[r.nome,r.formula,r.assistente?.join(' / ')||'Não se aplica',r.lider?.join(' / ')||'Não se aplica']));}
function render(){if(!storageError){const sync=sincronizarMaloteEstado(state);if(sync.alterado){try{localStorage.setItem(KEY,JSON.stringify(sync.estado));state=sync.estado;}catch{storageError='Não foi possível salvar a sincronização da quantidade de processos. Exporte um backup.';}}}if(!storageError){const base=preencherParticipantes(state,month);if(base.alterado){try{localStorage.setItem(KEY,JSON.stringify(base.estado));state=base.estado;}catch{storageError='Não foi possível salvar a base inicial neste navegador. Exporte um backup e verifique o espaço disponível.';}}}for(const r of Object.values(roots))r.replaceChildren();renderOverview();renderPeople();renderLaunch();renderResults();renderPolicies();for(const root of Object.values(roots))prepararTabelasVisuais(root);}
const restore=el('input');restore.type='file';restore.accept='.json';restore.id='garantia-backup-file';restore.hidden=true;restore.addEventListener('change',async()=>{try{const file=restore.files[0];if(!file)return;if(file.size>15*1024*1024)throw Error('Backup acima de 15 MB.');const parsed=JSON.parse(await file.text());if(parsed.versao!==2||!parsed.competencias||!Array.isArray(parsed.historico))throw Error('Backup inválido.');const clean=vazio();for(const [monthKey,data] of Object.entries(parsed.competencias)){if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(monthKey)||!data.metricas||!Array.isArray(data.participantes))throw Error('Estrutura do backup inválida.');for(const p of data.participantes)if(typeof p.nome!=='string'||!Object.hasOwn(PERFIS,p.perfil))throw Error('Participante inválido no backup.');const merged=mesclar(clean,{competencia:monthKey,metricas:data.metricas,participantes:data.participantes,arquivo:file.name});clean.competencias=merged.competencias;}pending=null;const d=modal('Restaurar backup');d.append(el('p','A restauração substituirá os dados locais. Salve o backup atual antes de continuar. As conferências serão reiniciadas.'));d.append(button('Baixar backup atual',()=>download('garantia-antes-restauracao.json',JSON.stringify(state))));d.append(button('Confirmar restauração',()=>{storageError='';if(persist(clean))d.close();},'primary'));}catch(e){alertUser(e.message);}finally{restore.value='';}});document.body.append(restore);
$('#competenciaGlobal')?.addEventListener('change',e=>{if(e.target.value){month=e.target.value;pending=null;render();}});render();

function conjuntoUpload(){const box=el('section',undefined,'g-import-master'),file=el('input');file.type='file';file.multiple=true;file.accept='.xlsx,.xls,.png,.jpg,.jpeg';file.setAttribute('aria-label','Conjunto de arquivos de Garantia');const status=el('p','Inclua a campanha-base e os arquivos auxiliares. Confira os vínculos e a prévia antes de aplicar.'),both=el('input');both.type='checkbox';const label=el('label','Malote dos DNs 4730, 4774 e 4977 vale para ambas as filiais do respectivo DN');label.append(both);const run=button('Conferir conjunto de planilhas',async()=>{run.disabled=true;try{if(!file.files.length)throw Error('Selecione os arquivos.');if(file.files.length>15)throw Error('Limite de 15 arquivos por conjunto.');const arquivos=[];for(const f of file.files){if(f.size>15*1024*1024)throw Error('Arquivo acima de 15 MB: '+f.name);status.textContent='Conferindo '+f.name;const data=await f.arrayBuffer(),hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',data)),b=>b.toString(16).padStart(2,'0')).join('');if(/\.(png|jpe?g)$/i.test(f.name)){const imagem=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f);});arquivos.push({nome:f.name,sha256:hash,imagem});}else{await window.CampanhasVendors?.xlsx?.();if(!window.XLSX)throw Error('Leitor Excel indisponível.');arquivos.push({nome:f.name,sha256:hash,wb:window.XLSX.read(data,{type:'array',cellNF:true,cellFormula:true})});}}const vinculos=both.checked?{'4730':['TERESINA','URUÇUI'],'4774':['RONDONOPOLIS','AGUA BOA'],'4977':['PORTO VELHO','JIPARANÁ']}:{};const r=prepararConjunto(arquivos,month,{estado:state,vinculos});sourceName='Conjunto de '+r.aplicados.length+' arquivos';preview({competencia:month,metricas:r.estado.competencias[month].metricas,participantes:r.estado.competencias[month].participantes,estadoPreparado:r.estado,avisos:['Referência Excel: '+money(r.conferencia.referencia)+'; '+r.conferencia.conferem+' pessoas conferem e '+r.conferencia.pendentes+' estão pendentes. O fechamento não é forçado para igualar o Excel.']});status.textContent='Prévia pronta. Nenhum dado aplicado antes de confirmar.';}catch(e){status.textContent=e.message;alertUser(e.message);}finally{run.disabled=false;}},'primary');box.append(el('h3','Importar todas as planilhas'),file,label,run,status);return box;}
function renderConferencia(root){if(!m().referenciaCampanha)return;const c=conferirCampanha(m()),box=el('section',undefined,'g-import-master');box.append(el('h3','Conferência com o Excel'),el('p','Referência original: '+money(c.referencia)+' · Soma calculada sem pendências: '+money(c.calculado)+' · '+c.conferem+' conferem · '+c.pendentes+' pendentes.'),el('strong',c.fechado?'Todos os valores conferem com a referência.':'Fechamento pendente — valores divergentes não são liberados.'));const details=el('details');details.append(el('summary','Comparar os '+c.linhas.length+' colaboradores'));table(details,['Colaborador','Excel','Cálculo antes da conferência','Resultado liberado para conferência','Situação'],c.linhas.map(r=>[r.nome,money(r.referencia),money(r.simulacao),money(r.calculado),r.status]));box.append(details,button('Baixar comparação com o Excel',()=>{const rows=[['Nome','Referência Excel','Cálculo antes da conferência','Calculado','Situação','Pendências'],...c.linhas.map(r=>[r.nome,r.referencia,r.simulacao,r.calculado,r.status,r.pendencias.join('; ')])];download('conferencia-garantia-'+month+'.csv','\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(';')).join('\r\n'),'text/csv;charset=utf-8');}));root.append(box);}
function renderFontes(root){if(!m().auditoriaFontes?.length)return;const box=el('section',undefined,'g-import-master');box.append(el('h3','Fontes anexadas e conferências'));for(const a of m().auditoriaFontes){const details=el('details');details.append(el('summary',a.arquivo+' · '+a.tipo+' · '+a.status),el('p',a.resumo));if(a.sha256)details.append(el('small','Identificação SHA-256: '+a.sha256));if(a.imagem&&/^data:image\/(png|jpeg);base64,/.test(a.imagem)){const image=el('img');image.src=a.imagem;image.alt=a.arquivo;image.style.maxWidth='100%';details.append(image);}if(a.registros?.length){const rows=el('div');details.addEventListener('toggle',()=>{if(details.open&&!rows.children.length){const keys=[...new Set(a.registros.flatMap(r=>Object.keys(r)))];table(rows,keys,a.registros.map(r=>keys.map(k=>r[k]??'—')));}});details.append(rows);}box.append(details);}root.append(box);}
// O segredo fica no fragmento do link entregue ao responsável, nunca no repositório ou no banco.
async function abrirAcessoPreparado(){const params=new URLSearchParams(location.hash.slice(1)),password=params.get('garantia-acesso'),cp=params.get('competencia')||'2026-09';if(!password)return;history.replaceState(null,'',location.pathname+location.search);if(password.length<12){alertUser('Link de acesso inválido.');return;}try{const [{supabase},{criarNuvem}]=await Promise.all([import('./supabase-config.js'),import('./garantia-nuvem.js?v=20261023')]);const candidate=criarNuvem(supabase),remote=await candidate.carregar(password);if(!remote||!/^\d{4}-(0[1-9]|1[0-2])$/.test(cp)||!remote.competencias[cp])throw Error('Dados preparados não encontrados nesta competência.');const open=()=>{cloud=candidate;cloudPassword=password;cloudStatus='Garantia importada aberta do Supabase';const next=structuredClone(remote);for(const [cp,v] of Object.entries(state.competencias))if(!next.competencias[cp])next.competencias[cp]=structuredClone(v);month=cp;const global=document.querySelector('#competenciaGlobal');if(global)global.value=cp;if(persist(next)){window.menuCampanhas?.abrirGarantia('lancamentos');}};const exists=Object.values(state.competencias[cp]?.metricas||{}).some(v=>Object.keys(v).some(k=>Object.hasOwn(CAMPOS,k)));if(exists&&JSON.stringify(state.competencias[cp])!==JSON.stringify(remote.competencias[cp])){const d=modal('Abrir dados importados de setembro');d.append(el('p','Há lançamentos locais nesta competência. Guarde o backup antes de abrir a versão importada da nuvem. Outras competências serão preservadas.'),button('Baixar backup local',()=>download('garantia-antes-importacao.json',JSON.stringify(state))),button('Abrir setembro importado',()=>{open();d.close();},'primary'));}else open();}catch(e){alertUser(e.message);}}
void abrirAcessoPreparado();
